// Custom worker entry. Re-exports SvelteKit's fetch handler as the default
// export, plus the Workflow classes Cloudflare needs to discover at deploy
// time. Wrangler bundles this entry; the SvelteKit `_worker.js` it imports
// is generated by `vite build` (run before `wrangler deploy`).
//
// The auto-generated `_worker.js` does not type-check cleanly under our
// strict TS config, so a hand-written `_worker.d.ts` next to the generated
// file (committed to git) provides the type signature TS uses; the actual
// JS is what wrangler bundles at deploy time.

import sveltekitWorker from '../.svelte-kit/cloudflare/_worker.js';
import { withEnv } from '$lib/server/env';
import { handleCronTick } from '$lib/server/triggers/cron-handler';

export { GenerateWorkflowFlow } from '$lib/server/workflows/gen-flow';
export { HealWorkflowFlow } from '$lib/server/workflows/heal-flow';

export default {
	fetch: sveltekitWorker.fetch.bind(sveltekitWorker),
	async scheduled(controller: ScheduledController, env: Env, ctx: ExecutionContext) {
		ctx.waitUntil(
			withEnv(env, async () => {
				try {
					const result = await handleCronTick(controller.scheduledTime);
					console.log(
						`[cron] tick scanned=${result.scanned} fired=${result.fired.length} skipped=${result.skipped.length}`
					);
				} catch (err) {
					console.error('[cron] handleCronTick threw', err);
				}
			})
		);
	}
} satisfies ExportedHandler<Env>;
